.title { font-weight: 700; font-size: 0.95rem; }
.message { font-size: 0.85rem; color: #cbd5e1; }
.close {
  background: none;
  border: none;
  color: #94a3b8;
  font-size: 0.95rem;
  cursor: pointer;
  padding: 0.2rem;
}
.close:hover { color: #e2e8f0; }

